1 = 1

    AND (
        operator_display_name LIKE CONCAT('%', #{keyword}, '%')
        OR operation_name LIKE CONCAT('%', #{keyword}, '%')
        OR target_type LIKE CONCAT('%', #{keyword}, '%')
        OR target_id LIKE CONCAT('%', #{keyword}, '%')
        OR request_path LIKE CONCAT('%', #{keyword}, '%')
